// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// The Graph page's features used together: the stored graph with unusual values, Undo after queries, layouts that
// keep what was arranged, "Add to graph" next to running work and other tabs, views, export, reload of preferences,
// and RDF 1.2 data (reifiers and triple terms) next to blank nodes, dates and numbers.
const REPOSITORY_ID = uniqueRepositoryId('graph-combinations');
const EX = 'http://example.org/combinations/';
const DATA = `
@prefix ex: <${EX}> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix geo: <http://www.w3.org/2003/01/geo/wgs84_pos#> .
ex:alice a ex:Person ; rdfs:label "Alice" ; ex:age 39 ; ex:born "1986-04-02"^^xsd:date ; ex:note "" ;
    ex:knows ex:bob ; ex:livesIn ex:oslo ; ex:address [ ex:street "Bryggen 1" ] .
ex:bob a ex:Person ; rdfs:label "Bob" ; ex:age 45 ; ex:livesIn ex:bergen ; ex:abstract "${'long text '.repeat(2500)}" .
ex:oslo a ex:City ; rdfs:label "Oslo" ; geo:lat 59.91 ; geo:long 10.75 .
ex:bergen a ex:City ; rdfs:label "Bergen" ; geo:lat 60.39 ; geo:long 5.32 .
<< ex:alice ex:knows ex:bob ~ ex:claim >> rdfs:label "Claim" ; ex:since 2001 .
ex:dave rdfs:label "Dave" ; ex:doubts <<( ex:alice ex:knows ex:bob )>> .
`;

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph combinations')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, { headers: { 'Content-Type': 'text/turtle' }, data: DATA });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.beforeEach(async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
});

const explorerOf = (page) => page.locator('.graph-explorer');
const node = (page, label) => explorerOf(page).locator('.graph-node')
    .filter({ has: page.locator('text', { hasText: new RegExp(`^${label}$`) }) }).first();

async function openGraph(page) {
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    return explorerOf(page);
}

async function loadAll(page) {
    const explorer = await openGraph(page);
    await explorer.getByRole('button', { name: 'Load 100 statements' }).click();
    await expect(node(page, 'Alice')).toBeAttached({ timeout: 30000 });
    await page.waitForTimeout(1500); // the layout settles
    return explorer;
}

async function runQuery(explorer, query) {
    await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    await explorer.locator('#sparql').fill(query);
    await explorer.getByRole('button', { name: 'Run query' }).click();
    await expect(explorer.getByRole('button', { name: 'Run query' })).toBeEnabled({ timeout: 30000 });
    await explorer.getByRole('button', { name: 'Close query editor' }).click();
}

/** The stored graph of this repository, as text, from the browser's database. */
function storedGraph(page, suffix = '') {
    return page.evaluate(([repositoryId, suffix]) => new Promise((resolve) => {
        const app = document.querySelector('#workbench-app');
        const serverIdentity = app?.getAttribute('data-workbench-server-identity');
        const appRepositoryId = app?.getAttribute('data-workbench-repository-id');
        if (!app || !serverIdentity || appRepositoryId !== repositoryId) return resolve('');
        const basePath = (app.getAttribute('data-workbench-base-path') || '').replace(/\/+$/, '');
        const scope = JSON.stringify(['repository-v2', basePath, serverIdentity, repositoryId]);
        const request = indexedDB.open('graph-field-workspaces', 1);
        request.onupgradeneeded = () => request.result.createObjectStore('workspaces');
        request.onsuccess = () => {
            const store = request.result.transaction('workspaces').objectStore('workspaces');
            const read = store.get(`workspace:${scope}${suffix}`);
            read.onsuccess = () => resolve(String(read.result ?? ''));
        };
    }), [REPOSITORY_ID, suffix]);
}

async function nodePositions(page) {
    return page.evaluate(() => Object.fromEntries([...document.querySelectorAll('.graph-explorer .graph-node')]
        .map((element) => [element.getAttribute('aria-label').split('. ').slice(0, 2).join('. '), element.getAttribute('transform')])));
}

test('a graph with an empty value and a 25,000-character value comes back whole after a reload', async ({ page }) => {
    const explorer = await loadAll(page);
    await expect.poll(() => storedGraph(page), { timeout: 10000 }).toContain('Alice');
    const stats = await explorer.locator('.graph-stats').textContent();
    await page.reload();
    await waitForRoute(page, 'graph');
    await expect(node(page, 'Alice')).toBeAttached({ timeout: 30000 });
    await expect(explorer.locator('.graph-stats')).toHaveText(stats);
});

test('a stored graph this version cannot read is kept, not saved over when the page opens', async ({ page }) => {
    await openGraph(page);
    const unreadable = JSON.stringify({ graph: { nodes: [{ id: 'urn:x', label: 'X', kind: 'nonsense' }], edges: [], revision: 1 } });
    await page.evaluate(([repositoryId, raw]) => new Promise((resolve) => {
        const app = document.querySelector('#workbench-app');
        const serverIdentity = app?.getAttribute('data-workbench-server-identity');
        const appRepositoryId = app?.getAttribute('data-workbench-repository-id');
        if (!app || !serverIdentity || appRepositoryId !== repositoryId) throw new Error('Workbench server identity is unavailable');
        const basePath = (app.getAttribute('data-workbench-base-path') || '').replace(/\/+$/, '');
        const scope = JSON.stringify(['repository-v2', basePath, serverIdentity, repositoryId]);
        const request = indexedDB.open('graph-field-workspaces', 1);
        request.onupgradeneeded = () => request.result.createObjectStore('workspaces');
        request.onsuccess = () => {
            const transaction = request.result.transaction('workspaces', 'readwrite');
            transaction.objectStore('workspaces').put(raw, `workspace:${scope}`);
            transaction.oncomplete = resolve;
        };
    }), [REPOSITORY_ID, unreadable]);
    await page.reload();
    await waitForRoute(page, 'graph');
    await expect(explorerOf(page).locator('.empty-state')).toBeVisible();
    await page.waitForTimeout(1500);
    expect(await storedGraph(page)).toBe(unreadable);
    expect(await storedGraph(page, ':unreadable')).toBe(unreadable);
});

test('Undo after a replacing query brings back the selection and the focus; a query without statements changes nothing',
    async ({ page }) => {
        const explorer = await loadAll(page);
        await node(page, 'Bob').click({ modifiers: ['Shift'] });
        await node(page, 'Oslo').click();
        const stats = await explorer.locator('.graph-stats').textContent();

        await runQuery(explorer, `SELECT ?x WHERE { BIND(1 AS ?x) }`);
        await expect(explorer.locator('.status-text')).toContainText('no statements');
        await expect(explorer.locator('.graph-stats')).toHaveText(stats);

        await runQuery(explorer, `CONSTRUCT { <${EX}oslo> ?p ?o } WHERE { <${EX}oslo> ?p ?o }`);
        await expect(explorer.locator('.graph-stats')).toHaveText('1 node · 0 links');
        await explorer.getByRole('button', { name: 'Undo the last graph change' }).click();
        await expect(explorer.locator('.graph-stats')).toHaveText(stats);
        await expect(node(page, 'Bob')).toHaveClass(/is-selected/);
        await expect(node(page, 'Oslo')).toHaveClass(/is-focused/);
    });

test('hiding, pinning, Values and added results leave the arranged nodes where they are', async ({ page }) => {
    const explorer = await loadAll(page);
    const moved = (before, after) => Object.keys(after).filter((key) => key in before && before[key] !== after[key]);
    let before = await nodePositions(page);
    await node(page, 'Dave').click();
    await explorer.getByRole('button', { name: 'Hide from the graph' }).click();
    await page.waitForTimeout(1200);
    expect(moved(before, await nodePositions(page))).toEqual([]);

    before = await nodePositions(page);
    await node(page, 'Bob').click();
    await explorer.getByRole('button', { name: 'Pin in place' }).click();
    await page.waitForTimeout(1200);
    expect(moved(before, await nodePositions(page))).toEqual([]);

    before = await nodePositions(page);
    await explorer.getByRole('button', { name: 'Show values and types as nodes' }).click();
    await page.waitForTimeout(2500);
    expect(moved(before, await nodePositions(page))).toEqual([]);
    await explorer.getByRole('button', { name: 'Show values and types as nodes' }).click();
    await page.waitForTimeout(1200);
    expect(moved(before, await nodePositions(page))).toEqual([]);

    const find = explorer.getByRole('combobox', { name: /Find a node/ });
    await find.fill('Dave');
    await explorer.getByRole('option', { name: /Search the repository/ }).click();
    await expect(node(page, 'Dave')).toBeAttached({ timeout: 30000 });
    await page.waitForTimeout(2000);
    expect(moved(before, await nodePositions(page))).toEqual([]);
});

test('an addition from another tab waits for the query running here, and both arrive', async ({ page, context }) => {
    const explorer = await loadAll(page);
    let release;
    const held = new Promise((resolve) => { release = resolve; });
    await page.route('**/repositories/*/graph', async (route) => {
        if ((route.request().postData() ?? '').includes('# slow')) await held;
        await route.continue();
    });
    await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    await explorer.locator('#sparql').fill(`# slow\nCONSTRUCT { <${EX}oslo> <${EX}twin> <${EX}reykjavik> } WHERE {}`);
    await explorer.getByRole('button', { name: 'Run query' }).click();

    const other = await context.newPage();
    await other.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(`<${EX}dave>`)}`);
    await waitForRoute(other, 'explore');
    await other.getByRole('button', { name: 'Add to graph' }).first().click();
    await other.waitForTimeout(500);
    release();

    await expect(explorer.locator('.graph-node', { hasText: 'reykjavik' })).toBeAttached({ timeout: 30000 });
    await expect(node(page, 'Dave')).toBeAttached({ timeout: 30000 });
    await other.close();
});

test('a Graph tab coming back into view shows the newer graph another tab saved', async ({ page, context }) => {
    const explorer = await loadAll(page);
    await expect.poll(() => storedGraph(page), { timeout: 10000 }).toContain('Alice');
    await page.evaluate(() => {
        Object.defineProperty(document, 'visibilityState', { value: 'hidden', configurable: true });
        document.dispatchEvent(new Event('visibilitychange'));
    });

    const other = await context.newPage();
    await other.setViewportSize({ width: 1440, height: 900 });
    await other.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(other, 'graph');
    const otherExplorer = explorerOf(other);
    await expect(otherExplorer.locator('.graph-node', { hasText: 'Alice' }).first()).toBeAttached({ timeout: 30000 });
    await otherExplorer.locator('.graph-node').filter({ has: other.locator('text', { hasText: /^Dave$/ }) }).first().click();
    await otherExplorer.getByRole('button', { name: 'Hide from the graph' }).click();
    await expect.poll(() => storedGraph(other), { timeout: 10000 }).not.toContain('"Dave"');
    await other.close();

    await expect(node(page, 'Dave')).toBeAttached();
    await page.evaluate(() => {
        Object.defineProperty(document, 'visibilityState', { value: 'visible', configurable: true });
        document.dispatchEvent(new Event('visibilitychange'));
    });
    await expect(node(page, 'Dave')).toHaveCount(0, { timeout: 10000 });
    await explorer.getByRole('button', { name: 'Undo the last graph change' }).click();
    await expect(node(page, 'Dave')).toBeAttached();
});

