test('an image exported from another view has the same colours as one exported from the graph', async ({ page }) => {
    const explorer = await loadAll(page);
    const download = async () => {
        await explorer.locator('summary[aria-label="Open workspace tools"]').click();
        const [file] = await Promise.all([page.waitForEvent('download'), explorer.getByRole('button', { name: 'Download SVG image' }).click()]);
        const chunks = [];
        for await (const chunk of await file.createReadStream()) chunks.push(chunk);
        return Buffer.concat(chunks).toString().replace(/<path d="[^"]*"/g, '');
    };
    const fromGraph = await download();
    await explorer.getByRole('tab', { name: 'Triples' }).click();
    const fromTable = await download();
    expect(fromTable).toBe(fromGraph);
    expect(fromTable).not.toContain('#888');
});

