test('RDF 1.2: a reifier and a reference are drawn to their statement, listed in their card, kept and exported',
    async ({ page }) => {
        const explorer = await loadAll(page);
        await expect(explorer.locator('.status-text')).toContainText('Loaded');
        const knows = await page.evaluate(() => [...document.querySelectorAll('.graph-explorer .edge')]
            .find((edge) => edge.querySelector('title').textContent.startsWith('Alice — knows → Bob'))?.getAttribute('data-edge-id'));
        const connectors = explorer.locator(`.statement-link[data-edge-id='${knows.replace(/'/g, "\\'")}']`);
        await expect(connectors).toHaveCount(2); // Claim reifies it, Dave doubts it

        await node(page, 'Claim').click();
        const card = explorer.locator('.node-details');
        await card.getByRole('button', { name: 'Alice knows Bob' }).click();
        await expect(explorer.locator('.statement-details h3')).toHaveText('knows');
        await expect(connectors.first()).toHaveClass(/is-selected/);
        await page.keyboard.press('Escape');

        await connectors.first().locator('path').click({ force: true });
        await expect(explorer.locator('.statement-details h3')).toHaveText('knows');

        await expect.poll(() => storedGraph(page), { timeout: 10000 }).toContain('statementLinks');
        await page.reload();
        await waitForRoute(page, 'graph');
        await expect(node(page, 'Alice')).toBeAttached({ timeout: 30000 });
        await expect(connectors).toHaveCount(2);

        await explorer.locator('summary[aria-label="Open workspace tools"]').click();
        const [file] = await Promise.all([page.waitForEvent('download'), explorer.getByRole('button', { name: 'Download Turtle' }).click()]);
        const chunks = [];
        for await (const chunk of await file.createReadStream()) chunks.push(chunk);
        const turtle = Buffer.concat(chunks).toString();
        expect(turtle).toContain(`rdf:reifies <<( <${EX}alice> <${EX}knows> <${EX}bob> )>>`);
        expect(turtle).toContain(`<${EX}doubts> <<( <${EX}alice> <${EX}knows> <${EX}bob> )>>`);
    });

