test('while the background is dragged the canvas drops node shadows, so it keeps up with the pointer', async ({ page }) => {
    const explorer = await loadAll(page);
    const box = await explorer.locator('.canvas-wrap').boundingBox();
    const start = await page.evaluate(({ x, y, w, h }) => {
        for (let i = 0; i < 400; i++) {
            const px = x + w * (0.05 + 0.9 * Math.random()), py = y + h * (0.2 + 0.6 * Math.random());
            if (document.elementFromPoint(px, py)?.classList.contains('graph-canvas')) return { x: px, y: py };
        }
        return null;
    }, { x: box.x, y: box.y, w: box.width, h: box.height });
    const shadow = () => page.evaluate(() => getComputedStyle(document.querySelector('.graph-explorer .graph-node rect')).filter);
    expect(await shadow()).not.toBe('none');
    await page.mouse.move(start.x, start.y);
    await page.mouse.down();
    for (let step = 1; step <= 10; step += 1) await page.mouse.move(start.x + step * 8, start.y);
    await expect(explorer.locator('.canvas-wrap')).toHaveAttribute('data-moving', '');
    expect(await shadow()).toBe('none');
    await page.mouse.up();
    await expect(explorer.locator('.canvas-wrap')).not.toHaveAttribute('data-moving', '');
    expect(await shadow()).not.toBe('none');
});
